const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nav=[['capture','✎','Capturar'],['material','▤','Tu material'],['graph','⌘','Constelaciones']];
let page='capture',filter='Todas',layer='Todas',graphMode='Grafo',entry='nota',selected='Calma',expanded=false,graphHistory=[],recording=false,paused=false,seconds=0,interrupted=false,offline=false,empty=false,notification=true;
let attachmentName='',screenProtection=true;
const captureIcons={record:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/>',save:'<path d="m22 2-7 20-4-9-9-4Z"/><path d="M22 2 11 13"/>'};
function captureAction(){const save=Boolean(draft.trim()||attachmentName),action=save?'save':'record',label=save?'Guardar reflexión':'Grabar nota de voz';return `<button class="primary capture-action" id="${action}" aria-label="${label}" title="${label}" ${recording?'disabled':''}><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${captureIcons[action]}</svg></button>`}
let draft=sessionStorage.getItem('espejo-proposal-draft')||'';
let notes=[{id:1,title:'Encontrar mi propio ritmo',type:'Texto',date:'Hoy · 10:42',status:'Lista',text:'Esta mañana salí a caminar sin mirar la hora. Me sorprendió lo mucho que necesitaba ese pequeño espacio.\n\nA veces confundo avanzar con estar siempre ocupado. Hoy sentí que podía hacer las cosas de otra manera: con más calma, prestando atención a lo que me pasa.\n\nQuiero acordarme de esto cuando vuelva el apuro. No necesito resolver todo hoy.'},{id:2,title:'Una idea volviendo a casa',type:'Audio',date:'Ayer · 18:16',status:'Transcribiendo',text:'Quizás darme tiempo también sea una forma de cuidarme.'},{id:3,title:'Lo que me llevo de esta semana',type:'Archivo',date:'12 oct · 21:05',status:'Lista',text:'Hubo conversaciones que me hicieron bien. Quiero dejarles más espacio.'},{id:4,title:'Sobre empezar de nuevo',type:'Texto',date:'11 oct · 09:30',status:'Pendiente',text:'No hace falta tener todo claro para empezar.'},{id:5,title:'Una pausa necesaria',type:'Audio',date:'10 oct · 17:20',status:'Revisar',text:'Hoy me di cuenta de que necesitaba parar. Respirar y volver a escucharme.'}];
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3200)}
function intro(k,title,desc){return `<div class="intro"><span class="eyebrow">${k}</span><h1>${title}</h1><p>${desc}</p></div>`}
const icons={capture:'<path d="m15 4 5 5M4 20l5-1L20 8a2 2 0 0 0-5-5L4 14Z"/>',material:'<path d="M5 4h14v16H5zM9 8h6M9 12h6M9 16h4"/>',graph:'<circle cx="12" cy="12" r="3"/><circle cx="4" cy="5" r="2"/><circle cx="20" cy="6" r="2"/><circle cx="18" cy="20" r="2"/><path d="m6 7 4 3m4 0 4-3m-5 8 4 3"/>'};
function navHTML(){return nav.map(([p,i,t])=>`<button data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${icons[p]}</svg></span><span>${t}</span></button>`).join('')}
function row(n){return `<article class="note-row"><span class="note-icon" aria-hidden="true">${n.type==='Audio'?'≋':n.type==='Archivo'?'▤':'✎'}</span><div><strong>${escapeHTML(n.title)}</strong><small>${n.type} · ${n.date}</small></div><button class="open-note quiet" data-read="${n.id}" aria-label="Abrir ${escapeHTML(n.title)}">↗</button><span class="pill ${n.status==='Lista'?'':'warn'}">${n.status==='Lista'?'✓ Lista':n.status}</span></article>`}
function capture(){return `<section class="capture">${intro('CAPTURAR','Dale lugar a lo que te pasa.','Una idea, una pregunta, algo que quieras recordar. A tu manera.')}${offline?'<div class="notice"><strong>Estás sin conexión</strong><p>Podés seguir escribiendo. Tus notas quedarán pendientes de sincronizar.</p></div>':''}${interrupted?'<div class="notice"><strong>Tu grabación se interrumpió</strong><p>Podés revisar el fragmento conservado antes de decidir cómo seguir.</p><button class="secondary" id="recover">Revisar audio recuperado ↗</button></div>':''}<div class="editor"><label for="draft" class="sr-only" hidden>Tu reflexión</label><textarea id="draft" aria-label="Tu reflexión" placeholder="¿Qué te gustaría sacar de tu cabeza?">${escapeHTML(draft)}</textarea><div id="attachment">${attachmentName?`<div class="attached">▤ ${escapeHTML(attachmentName)} <button id="remove-attachment" aria-label="Quitar adjunto">×</button></div>`:""}</div><div class="editor-foot"><div class="toolbar"><button class="quiet" id="attach">＋ <span>Archivo</span></button><button class="quiet" id="date">◷ <span>Fecha</span></button></div><div class="toolbar" id="capture-action">${captureAction()}</div></div></div><div class="save-hint"><span>◦ Borrador en este dispositivo</span><span id="draft-count">${draft.length?draft.length+' caracteres':'Sin apuro.'}</span></div><div class="invitation"><div><span class="eyebrow">UNA INVITACIÓN</span><h3>¿Qué te hizo bien hoy?</h3><p>Si te sirve, empezá por acá.</p></div><button id="invitation" aria-label="Responder invitación">Responder ↗</button></div><div class="section-line"><h2>Lo último que dejaste acá</h2><button class="quiet" data-page="material">Ver todo →</button></div>${empty?'<p>Todavía no hay notas. Este espacio empieza con vos.</p>':notes.slice(0,2).map(row).join('')}</section>`}
function material(){return `${intro('TU MATERIAL','Lo que vas dejando acá.','Tus notas, audios y archivos, con espacio para volver a leerlos.')}<div class="actions"><button class="secondary" id="sync">↻ Sincronizar</button><button class="quiet" id="backup">Respaldo e importación ↗</button><span class="meta">${offline?'Sin conexión · 1 pendiente':'✓ Estados actualizados'}</span></div><div class="filters">${['Todas','Texto','Audio','Archivo','Pendientes','Borradores'].map(f=>`<button data-filter="${f}" class="${filter===f?'active':''}" aria-pressed="${filter===f}">${f}</button>`).join('')}</div><input class="search" id="search" type="search" aria-label="Buscar en tu material" placeholder="Buscar en tu material…"><div id="note-list">${noteList('')}</div><p class="meta">Las copias de este dispositivo y del servidor se reúnen por nota. El estado te cuenta qué falta.</p>`}
function noteList(search){const found=empty?[]:notes.filter(n=>(filter==='Todas'||n.type===filter||(filter==='Pendientes'&&n.status!=='Lista')||(filter==='Borradores'&&n.status==='Borrador'))&&n.title.toLowerCase().includes(search.toLowerCase()));return found.length?found.map(row).join(''):`<div class="empty"><h2>${search?'No encontramos esa nota.':'Un espacio por llenar.'}</h2><p>${filter==='Borradores'?'Los borradores que conserves aparecerán acá.':'Probá otra búsqueda o guardá una nueva reflexión.'}</p><button class="secondary" data-page="capture">Ir a capturar</button></div>`}
function graph(){const nodes=[['Ritmo propio',250,160,'Todas'],['Calma',125,100,'Emociones'],['Trabajo',390,105,'Entidades'],['Darme tiempo',125,250,'Afirmaciones'],['Cuidarme',385,250,'Afirmaciones'],...(expanded?[['Una pausa',440,180,'Emociones'],['Caminar',245,290,'Entidades']]:[])];const shown=nodes.filter((n,i)=>i===0||layer==='Todas'||n[3]===layer);return `${intro('CONSTELACIONES','Encontrá un hilo.','Partí de una nota o una emoción. Seguí lo que te llama la atención.')}<div class="filters">${['nota','emoción'].map(e=>`<button class="${entry===e?'active':''}" data-entry="${e}" aria-pressed="${entry===e}">Por ${e}</button>`).join('')}</div><div class="card"><label class="meta" for="graph-source">${entry==='nota'?'Nota de partida':'Emoción de partida'}</label><div class="setting-row"><select id="graph-source" aria-label="Punto de partida">${(entry==='nota'?['Encontrar mi propio ritmo','Lo que me llevo de esta semana','Sobre empezar de nuevo']:['Calma','Alegría','Tristeza']).map(n=>`<option>${n}</option>`).join('')}</select><div class="actions">${['Grafo','Lista'].map(m=>`<button class="${graphMode===m?'secondary':'quiet'}" data-mode="${m}" aria-pressed="${graphMode===m}">${m}</button>`).join('')}</div></div></div><div class="filters" aria-label="Tipos de extracción">${['Todas','Emociones','Entidades','Afirmaciones'].map(l=>`<button data-layer="${l}" class="${layer===l?'active':''}" aria-pressed="${layer===l}">${l}</button>`).join('')}</div><div class="split"><div>${graphMode==='Grafo'?`<div class="graph"><svg viewBox="0 0 500 350" role="img" aria-label="Conexiones de ejemplo. Los mismos elementos están disponibles en Lista.">${shown.slice(1).map(n=>`<line x1="250" y1="160" x2="${n[1]}" y2="${n[2]}"/>`).join('')}${shown.map((n,i)=>`<g tabindex="0" role="button" aria-label="Explorar ${n[0]}" data-node="${n[0]}"><circle cx="${n[1]}" cy="${n[2]}" r="${i===0?32:19}" fill="${n[3]==='Emociones'?'#7f9979':n[3]==='Entidades'?'#759aab':n[3]==='Afirmaciones'?'#b39d6c':'#b8d6ce'}"/><text x="${n[1]}" y="${n[2]+(i===0?51:37)}" text-anchor="middle">${n[0]}</text></g>`).join('')}</svg><div class="graph-tools"><button id="graph-back" ${graphHistory.length?'':'disabled'}>← Volver</button><button id="arrange">Ordenar</button></div></div>`:`<div class="card">${shown.map(n=>`<button class="scenario wide" data-node="${n[0]}">${n[0]} <small>· ${n[3]}</small></button>`).join('')}</div>`}<p class="meta">Seleccioná una conexión para ver de dónde viene. Las ramas exploradas permanecen visibles.</p></div><aside class="card"><span class="eyebrow">${selected==='Calma'?'EMOCIÓN':'CONEXIÓN'}</span><h2>${selected}</h2><small>Encontrar mi propio ritmo · Hoy</small><blockquote class="quote">“Hoy sentí que podía hacer las cosas de otra manera: con más calma.”</blockquote><button class="secondary wide" data-read="1">Leer nota completa ↗</button><button class="quiet wide" id="expand">Explorar conexiones →</button></aside></div><button class="quiet" id="refresh-graph">↻ Actualizar conexiones</button>`}
function settings(){return `<div class="reader">${intro('AJUSTES','A tu tiempo.','Elegí cómo querés que El Espejo te acompañe.')}<section class="card"><h2>Invitaciones para escribir</h2><p>Una pregunta por día. Responder es siempre opcional.</p><div class="setting-row"><div><strong>Recibir invitaciones</strong><p class="meta">En este dispositivo</p></div><button id="notify" class="toggle ${notification?'':'off'}" role="switch" aria-checked="${notification}" aria-label="Recibir invitaciones"></button></div><div class="fields"><label>Horario local<input type="time" value="20:30"></label><label>Zona horaria<select><option>America/Argentina/Buenos_Aires</option><option>Europe/Madrid</option></select></label></div><p class="meta">La zona elegida se conserva aunque viajes. La entrega depende del dispositivo.</p><div class="actions"><button class="primary" id="save-settings">Guardar horario</button><button class="quiet" id="test-notification">Enviar prueba</button></div></section><section class="card"><h2>Tus documentos</h2><p>Descargá un respaldo de tus textos o recuperá documentos de un archivo.</p><button class="secondary" id="backup">Respaldo e importación ↗</button></section><button class="quiet" data-page="login">↗ Cerrar sesión en este dispositivo</button></div>`}
function login(){return `<section class="login"><a class="brand" href="#capture"><img src="el-espejo-mark.png" alt="">El Espejo</a><h1>Volvé a tu espacio.</h1><p>Lo que te pasa merece un lugar.</p><form id="login-form" class="fields"><label>Usuario<input required autocomplete="username" placeholder="Tu usuario"></label><label>Contraseña<div class="actions"><input style="flex:1;width:0" required id="password" type="password" autocomplete="current-password" placeholder="Tu contraseña"><button type="button" id="show-password" aria-label="Mostrar contraseña">◉</button></div></label><button class="primary wide">Entrar</button><button type="button" class="secondary" id="google">Continuar con Google</button></form><p class="meta">Acceso simulado para recorrer la propuesta.</p></section>`}
function render(){ $('#desktop-nav').innerHTML=navHTML();$('#mobile-nav').innerHTML=navHTML();$('#main').innerHTML=({capture,material,graph,settings,login}[page]||capture)();$('#main').classList.toggle('recording-space',recording);drawRecorder();bind(); }
function go(p){page=p;location.hash=p;render();window.scrollTo({top:0});$('#main').focus({preventScroll:true})}
function bind(){const d=$('#draft');if(d)d.oninput=()=>{draft=d.value;sessionStorage.setItem('espejo-proposal-draft',draft);$('#capture-action').innerHTML=captureAction();$('#draft-count').textContent=draft.length+' caracteres'};const s=$('#search');if(s)s.oninput=()=>$('#note-list').innerHTML=noteList(s.value);const f=$('#login-form');if(f)f.onsubmit=e=>{e.preventDefault();go('capture')};const gs=$('#graph-source');if(gs)gs.onchange=()=>{expanded=false;graphHistory=[];layer='Todas';selected=gs.value;render()};}
let lastFocus;
function modal(title,body){lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><h2 id="modal-title">${title}</h2><button id="close-modal" aria-label="Cerrar diálogo">×</button></header>${body}</section></div>`;$('#close-modal').focus()}
function closeModal(){$('#overlay').innerHTML='';if(lastFocus?.isConnected)lastFocus.focus()}
function read(id){const n=notes.find(n=>n.id===Number(id));if(!n)return;modal(escapeHTML(n.title),`<p class="meta">${n.type} · ${n.date} · ${n.status}</p>${n.type==='Audio'?'<div class="card"><strong>≋ Audio · 02:14</strong><p>Reproductor de ejemplo</p><button class="secondary" id="play-audio">▷ Escuchar muestra</button><button class="quiet" id="download-audio">Descargar audio</button></div>':''}<div class="reader-body">${escapeHTML(n.text)}</div>${n.status==='Revisar'?'<div class="notice"><strong>El audio está conservado.</strong><p>Falló el procesamiento. Podés reintentar desde la transcripción.</p></div>':''}<div class="actions" style="margin-top:24px"><button class="secondary" data-graph-note="${n.id}">Ver conexiones</button>${n.status!=='Lista'?`<button class="secondary" data-retry="${n.id}">Reintentar procesamiento</button>`:''}${n.type==='Audio'?`<button class="quiet" data-reupload="${n.id}">Volver a subir audio</button>`:''}<button class="danger" data-delete="${n.id}">Eliminar</button></div>`)}
function drawRecorder(){if(!recording){$('#recorder').innerHTML='';return}$('#recorder').innerHTML=`<section class="recorder" aria-label="Grabación de ejemplo"><div><strong><span class="record-dot">●</span>${paused?'En pausa':'Grabando'} <span id="timer">${formatTime(seconds)}</span></strong><small>Simulación · no se usa el micrófono</small><small class="screen-protection ${screenProtection?'':'unavailable'}">${screenProtection?'◦ Pantalla activa mientras grabás':'◷ No pudimos mantener la pantalla activa'}</small><div class="waves" aria-hidden="true">${Array.from({length:24},(_,i)=>`<i style="--h:${8+(i*17)%22}px;--d:${i*.05}s;${paused?'animation-play-state:paused':''}"></i>`).join('')}</div></div><div class="actions"><button class="secondary" id="pause-record">${paused?'Continuar':'Pausar'}</button><button class="primary" id="stop-record">■ Terminar</button></div></section>`}
function formatTime(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
setInterval(()=>{if(recording&&!paused){seconds++;if($('#timer'))$('#timer').textContent=formatTime(seconds)}},1000);
function finishRecord(){recording=false;interrupted=false;notes.unshift({id:Date.now(),title:'Nota de voz · '+formatTime(seconds),type:'Audio',date:'Hoy · recién',status:offline?'Pendiente':'Transcribiendo',text:'Audio de ejemplo. La grabación y su persistencia están simuladas en esta propuesta.'});render();toast('Audio de ejemplo agregado a Tu material')}
function backup(){modal('Respaldo e importación','<p>Tus textos y transcripciones, en un archivo JSON portable.</p><div class="notice"><strong>El respaldo JSON no incluye audios.</strong><p>Descargalos desde cada nota de voz si querés conservar una copia.</p></div><div class="actions"><button class="primary" id="export">Descargar ejemplo JSON</button><button class="secondary" id="import">Probar importación</button></div><p class="meta">En la app, los documentos importados también se envían a procesar. Aquí se muestra el flujo con datos de ejemplo.</p>')}
function scenarios(){modal('Recorré los estados','<p>Esta propuesta usa datos ficticios. No graba, sube ni elimina contenido real.</p><button class="scenario" id="scenario-record">01 · Iniciar grabación de ejemplo</button><button class="scenario" id="scenario-interrupt">02 · Simular bloqueo e interrupción</button><button class="scenario" id="scenario-error">03 · Audio conservado, procesamiento fallido</button><button class="scenario" id="scenario-offline">04 · Alternar conexión</button><button class="scenario" id="scenario-empty">05 · Alternar material vacío</button><button class="scenario" data-page="login">06 · Ver acceso</button><button class="scenario" id="scenario-screen">07 · Alternar protección de pantalla</button><p class="meta">Para mobile, reducí la ventana. Navegación inferior a partir de 700 px.</p>')}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-node]');if(!b)return;
if(b.dataset.page){closeModal();go(b.dataset.page);return}if(b.dataset.read){read(b.dataset.read);return}if(b.dataset.filter){filter=b.dataset.filter;render();return}if(b.dataset.layer){layer=b.dataset.layer;render();return}if(b.dataset.mode){graphMode=b.dataset.mode;render();return}if(b.dataset.entry){entry=b.dataset.entry;expanded=false;layer='Todas';graphHistory=[];render();return}if(b.dataset.node){selected=b.dataset.node;render();return}if(b.dataset.graphNote){closeModal();go('graph');return}if(b.dataset.delete){const id=Number(b.dataset.delete);modal('¿Eliminar esta nota?','<p>En la app, esta acción elimina el documento y sus datos relacionados. Confirmá para quitar la nota de ejemplo.</p><button class="secondary" id="cancel-delete">Conservar</button><button class="danger" id="confirm-delete" data-id="'+id+'">Eliminar nota de ejemplo</button>');return}if(b.dataset.retry){const n=notes.find(n=>n.id===Number(b.dataset.retry));n.status='Transcribiendo';closeModal();render();toast('Reintento simulado desde el contenido conservado');return}if(b.dataset.reupload){toast('Nueva subida simulada del audio conservado');return}
switch(b.id){case 'scenarios':scenarios();break;case 'scenario-screen':screenProtection=!screenProtection;closeModal();recording=true;go('capture');toast('Estado de protección de pantalla simulado');break;case 'close-modal':case 'cancel-delete':closeModal();break;case 'save':if(!draft.trim()&&!attachmentName)return;notes.unshift({id:Date.now(),title:draft.trim().slice(0,65)||attachmentName,text:draft||'Contenido de archivo simulado. No se ha leído ni subido el archivo seleccionado.',type:attachmentName?'Archivo':'Texto',date:'Hoy · recién',status:offline?'Pendiente':'Lista'});draft='';attachmentName='';sessionStorage.removeItem('espejo-proposal-draft');render();toast('Reflexión de ejemplo guardada');break;
case 'record':case 'scenario-record':closeModal();recording=true;paused=false;seconds=0;go('capture');break;case 'pause-record':paused=!paused;drawRecorder();break;case 'stop-record':finishRecord();break;
case 'scenario-interrupt':closeModal();recording=false;paused=false;interrupted=true;seconds=Math.max(seconds,134);go('capture');break;case 'recover':modal('Recuperamos parte de tu audio',`<p>La grabación se interrumpió cuando la pantalla se bloqueó.</p><div class="card"><strong>≋ Fragmento conservado · ${formatTime(seconds)}</strong><p>Estado de ejemplo. En la implementación, se debe verificar cuánto audio está efectivamente guardado.</p></div><p>Podés guardar lo recuperado o continuar en un nuevo segmento.</p><div class="actions"><button class="primary" id="keep-recovered">Guardar fragmento</button><button class="secondary" id="continue-recovered">Continuar grabando</button></div>`);break;
case 'keep-recovered':closeModal();finishRecord();break;case 'continue-recovered':closeModal();interrupted=false;recording=true;paused=false;render();toast('Continuación simulada en un nuevo segmento');break;
case 'scenario-error':closeModal();empty=false;go('material');read(5);break;case 'scenario-offline':offline=!offline;closeModal();render();toast(offline?'Vista sin conexión':'Conexión restablecida');break;case 'scenario-empty':empty=!empty;closeModal();go('material');break;
case 'invitation':if(draft.trim())notes.unshift({id:Date.now(),title:draft.slice(0,65),type:'Texto',date:'Hoy',status:'Borrador',text:draft});draft='¿Qué me hizo bien hoy?\n\n';sessionStorage.setItem('espejo-proposal-draft',draft);render();$('#draft').focus();toast('Invitación abierta. El borrador anterior se conserva.');break;
case 'attach':modal('Adjuntar un archivo','<p>Texto o Markdown (.txt, .md). El contenido se guarda como documento.</p><label class="fields">Archivo de ejemplo<input type="file" id="file" accept=".txt,.md,text/plain,text/markdown"></label><p class="meta">La selección es local. No se sube ningún archivo.</p>');$('#file').onchange=()=>{const f=$('#file').files[0];if(f){attachmentName=f.name;closeModal();render();toast('Archivo seleccionado para la propuesta')}};break;case 'remove-attachment':attachmentName='';render();break;
case 'date':modal('Fecha de la reflexión','<p>Si esto pasó otro día, podés indicarlo.</p><div class="fields"><label>Fecha<input id="authored-date" type="date" value="2026-10-14"></label><label>Hora<input type="time" value="10:42"></label><button class="primary" id="confirm-date">Usar esta fecha</button></div>');break;case 'confirm-date':closeModal();toast('Fecha seleccionada para la propuesta');break;
case 'sync':if(offline){toast('Sin conexión. Las notas siguen pendientes.');return}notes.forEach(n=>{if(n.status==='Pendiente')n.status='Lista'});render();toast('Sincronización de ejemplo completada');break;case 'backup':backup();break;
case 'export':{const blob=new Blob([JSON.stringify({prototype:true,documents:notes.filter(n=>n.type!=='Audio').map(n=>({title:n.title,content:n.text}))},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='el-espejo-ejemplo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Archivo con textos ficticios descargado');break}
case 'import':modal('Importar documentos','<p>Vista previa de una importación de ejemplo.</p><div class="card"><strong>3 documentos compatibles</strong><p>Se conservan fecha y contenido. Si una identidad existente tiene contenido distinto, se informa el conflicto.</p></div><button class="primary" id="confirm-import">Importar ejemplo y procesar</button>');break;case 'confirm-import':closeModal();toast('Importación simulada · 3 documentos en procesamiento');break;
case 'expand':graphHistory.push({expanded,selected,layer});expanded=true;render();toast('Rama agregada al mismo grafo');break;case 'graph-back':{const s=graphHistory.pop();if(s){expanded=s.expanded;selected=s.selected;layer=s.layer;render()}break}case 'arrange':toast('Distribución ordenada · posiciones del ejemplo');break;case 'refresh-graph':toast('Conexiones de ejemplo actualizadas · filtro conservado');break;
case 'notify':notification=!notification;render();break;case 'save-settings':toast('Horario guardado en la simulación');break;case 'test-notification':toast('Ejemplo de invitación: ¿Qué te hizo bien hoy?');break;case 'show-password':{const p=$('#password');p.type=p.type==='password'?'text':'password';b.setAttribute('aria-label',p.type==='password'?'Mostrar contraseña':'Ocultar contraseña');break}case 'google':go('capture');toast('Acceso con Google simulado');break;case 'play-audio':toast('Reproductor ilustrativo · sin archivo real');break;case 'download-audio':toast('La muestra no contiene un archivo de audio real');break;case 'confirm-delete':notes=notes.filter(n=>n.id!==Number(b.dataset.id));closeModal();render();toast('Nota de ejemplo eliminada');break;
}});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-node]')&&['Enter',' '].includes(e.key)){e.preventDefault();selected=e.target.dataset.node;render()}const modalEl=$('.modal');if(!modalEl)return;if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const f=[...modalEl.querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')];if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(['capture','material','graph','settings','login'].includes(p)&&p!==page){page=p;render()}});
if(['capture','material','graph','settings','login'].includes(location.hash.slice(1)))page=location.hash.slice(1);render();
